function confetti(amount){if(reduced)return;const layer=$('fx');while(layer.children.length>120)layer.firstChild.remove();for(let i=0;i<amount;i++){const p=document.createElement('span');p.className='particle';p.style.setProperty('--color',['#ffcd33','#b09bd6','#8fbd9e','#fff8e4','#f3a18b'][i%5]);const x=innerWidth*(.25+Math.random()*.5),y=innerHeight*.48;p.style.left=x+'px';p.style.top=y+'px';for(let j=0;j<6;j++)p.append(document.createElement('i'));layer.append(p);const dx=(Math.random()-.5)*innerWidth*.9,dy=180+Math.random()*260,turn=Math.random()*900;const anim=p.animate([{transform:'translate3d(0,0,0) rotateX(0) rotateY(0)',opacity:1},{transform:`translate3d(${dx*.5}px,${-dy}px,${Math.random()*180}px) rotateX(${turn*.5}deg) rotateY(160deg)`,opacity:1,offset:.42},{transform:`translate3d(${dx}px,${innerHeight*.65}px,0) rotateX(${turn}deg) rotateY(440deg)`,opacity:0}],{duration:1700+Math.random()*1200,easing:'cubic-bezier(.15,.4,.5,1)'});anim.onfinish=()=>p.remove()}}
